/* =========================================================================
 * MediaWiki:ClothListPage.js
 * 换装图鉴 —— 客户端渲染 + 分页显示 + 全量筛选 + 船名搜索
 *             + 批量 imageinfo + 懒加载节流 + 指数退避重试 + 熔断
 * ========================================================================= */
(function () {
    'use strict';

    /* ======================= 配置 ======================= */
    var CONFIG = {
        jsonPage : 'Module:ClothList/json',
        cardRoot : '#CardSelectTr',
        pageSize : 20,
        imgWidth : 150,
        typeIconWidth : 30,
        rootMargin : '200px',
        searchDebounce: 200,                 // 搜索防抖（毫秒）
        fields   : ['舰种', '阵营', '主题', '价格', '获取方式',
                    '表情差分', '立绘类型', '背景类型', '背景物件','实装时间']
    };

    var IMG_MAX_CONCURRENT = 2;
    var IMG_MIN_INTERVAL   = 150;
    var IMG_MAX_ATTEMPTS   = 5;
    var CIRCUIT_THRESHOLD  = 3;
    var CIRCUIT_COOLDOWN   = 30000;

    /* ======================= 状态 ======================= */
    var items       = [];
    var filtered    = [];
    var filters     = {};
    var currentPage = 1;
    var $root       = null;
    var $pager      = null;
    var $searchBar  = null;
    var $searchInput = null;
    var $searchClear = null;
    var searchKeyword = '';
    var searchTimer   = null;
    var started     = false;

    /* 文件名 → 真实 URL 的缓存；null 表示解析失败 */
    var resolvedUrlCache = {};

    /* ======================= 图片懒加载 / 节流 / 重试 / 熔断 ======================= */
    var imgObserver      = null;
    var imgQueue         = [];
    var imgTimer         = null;
    var imgActive        = 0;
    var imgLastSend      = 0;
    var circuitOpen      = false;
    var circuitTimer     = null;
    var consecutiveFails = 0;

    function initImgObserver() {
        if (imgObserver) return;
        if (!('IntersectionObserver' in window)) return;

        imgObserver = new IntersectionObserver(function (entries) {
            entries.forEach(function (entry) {
                if (entry.isIntersecting) {
                    var img = entry.target;
                    imgObserver.unobserve(img);
                    enqueueImg(img, 0);
                }
            });
        }, { rootMargin: CONFIG.rootMargin });
    }

    function enqueueImg(img, attempt) {
        imgQueue.push({ img: img, attempt: attempt || 0 });
        scheduleImgPump(0);
    }

    function scheduleImgPump(delay) {
        if (imgTimer) return;
        imgTimer = setTimeout(function () {
            imgTimer = null;
            pumpImgQueue();
        }, delay);
    }

    function pumpImgQueue() {
        if (circuitOpen) return;
        if (imgActive >= IMG_MAX_CONCURRENT) return;
        if (!imgQueue.length) return;

        var now   = Date.now();
        var since = now - imgLastSend;

        if (since < IMG_MIN_INTERVAL) {
            scheduleImgPump(IMG_MIN_INTERVAL - since);
            return;
        }

        var item = imgQueue.shift();
        loadOneImg(item);
        pumpImgQueue();
    }

    function loadOneImg(item) {
        var img     = item.img;
        var attempt = item.attempt;
        var src     = img.getAttribute('data-src');

        if (!src) { pumpImgQueue(); return; }

        imgActive++;
        imgLastSend = Date.now();

        var finished = false;

        function finish(ok) {
            if (finished) return;
            finished = true;
            imgActive--;
            img.onload = img.onerror = null;

            if (ok) {
                consecutiveFails = 0;
                img.classList.remove('cloth-img-pending', 'cloth-img-failed');
                img.title = '';
                img.style.cursor = '';
                pumpImgQueue();
                return;
            }

            consecutiveFails++;
            if (consecutiveFails >= CIRCUIT_THRESHOLD) {
                tripCircuit();
            }

            var next = attempt + 1;
            if (next <= IMG_MAX_ATTEMPTS) {
                var delay = Math.min(500 * Math.pow(2, next - 1), 16000);
                setTimeout(function () {
                    enqueueImg(img, next);
                }, delay);
                return;
            }

            markImgFailed(img, src);
        }

        img.onload  = function () { finish(true); };
        img.onerror = function () { finish(false); };

        var finalSrc = src;
        if (attempt > 0) {
            finalSrc += (src.indexOf('?') < 0 ? '?' : '&') + '_r=' + Date.now();
        }
        img.src = finalSrc;
    }

    function tripCircuit() {
        circuitOpen = true;
        if (circuitTimer) clearTimeout(circuitTimer);
        circuitTimer = setTimeout(function () {
            circuitOpen      = false;
            circuitTimer     = null;
            consecutiveFails = 0;
            pumpImgQueue();
        }, CIRCUIT_COOLDOWN);
    }

    function markImgFailed(img, src) {
        var w = CONFIG.imgWidth || 150;
        var svg =
            '<svg xmlns="http://www.w3.org/2000/svg" width="' + w + '" height="' + w + '">' +
              '<rect width="100%" height="100%" fill="#f2f2f2"/>' +
              '<text x="50%" y="50%" text-anchor="middle" dy=".35em" ' +
                    'fill="#888" font-size="13">点击重试</text>' +
            '</svg>';
        img.src = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg);
        img.classList.add('cloth-img-failed');
        img.title = '图片加载失败，点击重试';
        img.style.cursor = 'pointer';

        img.onclick = function (e) {
            e.preventDefault();
            e.stopPropagation();

            img.classList.remove('cloth-img-failed');
            img.title = '';
            img.style.cursor = '';
            img.onclick = null;

            img.removeAttribute('src');
            enqueueImg(img, 0);
        };
    }

    function resetImgQueue() {
        imgQueue.length = 0;
        if (imgTimer) { clearTimeout(imgTimer); imgTimer = null; }

        if (imgObserver) { imgObserver.disconnect(); imgObserver = null; }
        initImgObserver();
    }

    /* ======================= 批量 URL 解析 ======================= */
    function collectFileNames(slice) {
        var names = {};

        slice.forEach(function (item) {
            var raw      = item.raw;
            var shipName = trim(raw['船名']);
            var shipType = trim(raw['舰种']);
            var clothTag = trim(raw['换装']);

            if (shipName) {
                var imgFile = shipName + clothTag + '.jpg';
                if (!(imgFile in resolvedUrlCache)) names[imgFile] = true;
            }
            if (shipType) {
                var typeFile = 'ShipType-' + shipType + '.png';
                if (!(typeFile in resolvedUrlCache)) names[typeFile] = true;
            }
        });

        return Object.keys(names);
    }

    function batchResolveUrls(fileNames) {
        var dfd = $.Deferred();

        if (!fileNames.length) { dfd.resolve(); return dfd.promise(); }

        var batches = [];
        for (var i = 0; i < fileNames.length; i += 50) {
            batches.push(fileNames.slice(i, i + 50));
        }

        var idx = 0;
        function next() {
            if (idx >= batches.length) { dfd.resolve(); return; }

            var batch  = batches[idx++];
            var titles = batch.map(function (n) { return 'File:' + n; }).join('|');

            new mw.Api().get({
                action       : 'query',
                format       : 'json',
                formatversion: 2,
                prop         : 'imageinfo',
                iiprop       : 'url',
                titles       : titles
            }).done(function (res) {
                var pages      = (res.query && res.query.pages) || [];
                var normalized = (res.query && res.query.normalized) || [];

                var normMap = {};
                normalized.forEach(function (n) { normMap[n.from] = n.to; });

                pages.forEach(function (p) {
                    var title = p.title || '';
                    var name  = title.replace(/^File:/, '');
                    var url   = (p.imageinfo && p.imageinfo[0] && p.imageinfo[0].url) || null;

                    resolvedUrlCache[name] = url;

                    for (var from in normMap) {
                        if (normMap[from] === title) {
                            resolvedUrlCache[from.replace(/^File:/, '')] = url;
                        }
                    }
                });

                batch.forEach(function (n) {
                    if (!(n in resolvedUrlCache)) resolvedUrlCache[n] = null;
                });

                next();
            }).fail(function () {
                batch.forEach(function (n) {
                    if (!(n in resolvedUrlCache)) resolvedUrlCache[n] = null;
                });
                next();
            });
        }

        next();
        return dfd.promise();
    }

    /* ======================= 样式 ======================= */
    function addStyle() {
        mw.util.addCSS(
            '.cloth-pager{display:flex;flex-wrap:wrap;align-items:center;justify-content:center;' +
                'gap:.4em;margin:1em 0;font-size:.9em;clear:both;}' +
            '.cloth-pager-info{opacity:.7;margin-right:.8em;}' +
            '.cloth-pager-nav{display:inline-flex;flex-wrap:wrap;gap:.25em;}' +
            '.cloth-pager-btn{display:inline-block;min-width:2.2em;padding:.3em .6em;text-align:center;' +
                'border:1px solid rgba(128,128,128,.5);border-radius:4px;background:transparent;' +
                'color:inherit;text-decoration:none;cursor:pointer;line-height:1.2;}' +
            '.cloth-pager-btn:hover{background:rgba(128,160,220,.25);text-decoration:none;}' +
            '.cloth-pager-btn.current{background:#3b7bd4;border-color:#3b7bd4;color:#fff;cursor:default;}' +
            '.cloth-pager-btn.disabled{opacity:.35;pointer-events:none;}' +
            '.cloth-pager-ellipsis{padding:0 .2em;opacity:.5;}' +
            '.cloth-loading,.cloth-empty{width:100%;padding:2em 0;text-align:center;opacity:.7;}' +
            '.cloth-error{width:100%;padding:2em 0;text-align:center;color:#c33;}' +
            '.cloth-img-failed{outline:1px dashed rgba(204,51,51,.5);}' +
            /* 搜索栏 */
            '.cloth-search-bar{display:flex;justify-content:flex-end;align-items:center;' +
                'gap:.4em;margin:.6em 0;}' +
            '.cloth-search-wrap{position:relative;display:inline-flex;align-items:center;}' +
            '.cloth-search-input{width:220px;padding:.35em 1.8em .35em .7em;' +
                'border:1px solid rgba(128,128,128,.5);border-radius:4px;' +
                'background:transparent;color:inherit;font-size:.9em;box-sizing:border-box;}' +
            '.cloth-search-input:focus{outline:none;border-color:#3b7bd4;' +
                'box-shadow:0 0 0 2px rgba(59,123,212,.2);}' +
            '.cloth-search-clear{position:absolute;right:.35em;top:50%;transform:translateY(-50%);' +
                'border:none;background:transparent;color:inherit;opacity:.5;cursor:pointer;' +
                'font-size:1.1em;line-height:1;padding:0 .2em;display:none;}' +
            '.cloth-search-clear:hover{opacity:1;}' +
            '.cloth-search-hint{font-size:.85em;opacity:.7;margin-right:.4em;}'
        );
    }

    /* ======================= 工具 ======================= */
    function trim(s) {
        return (s === undefined || s === null) ? '' : String(s).replace(/^\s+|\s+$/g, '');
    }

    function filePathUrl(fileName) {
        return mw.util.getUrl('Special:FilePath') + '/' + encodeURIComponent(fileName);
    }

    /* ======================= 数据获取 ======================= */
    function fetchJson() {
        var dfd = $.Deferred();

        new mw.Api().get({
            action       : 'query',
            format       : 'json',
            formatversion: 2,
            prop         : 'revisions',
            rvprop       : 'content',
            rvslots      : 'main',
            titles       : CONFIG.jsonPage
        }).done(function (res) {
            var pages = res && res.query && res.query.pages;
            var page  = pages && pages[0];

            if (!page || page.missing !== undefined) {
                dfd.reject('页面不存在：' + CONFIG.jsonPage);
                return;
            }

            var rev  = page.revisions && page.revisions[0];
            var slot = rev && rev.slots && rev.slots.main;
            var text = slot ? (slot.content !== undefined ? slot.content : slot['*']) : null;

            if (text === null || text === undefined) {
                dfd.reject('无法读取内容：' + CONFIG.jsonPage);
                return;
            }

            var data;
            try {
                data = JSON.parse(text);
            } catch (e) {
                dfd.reject('JSON 解析失败：' + e.message);
                return;
            }

            if (!$.isArray(data)) {
                dfd.reject('JSON 格式错误：期望数组');
                return;
            }

            dfd.resolve(data);
        }).fail(function (err) {
            dfd.reject('接口请求失败：' + err);
        });

        return dfd.promise();
    }

    /* ======================= 数据预处理 ======================= */
    function parseClothDate(s) {
        s = trim(s);
        if (!s) return -Infinity;

        var m = s.match(/^(\d{4})年(\d{1,2})月(\d{1,2})日/);
        if (m) {
            return new Date(+m[1], +m[2] - 1, +m[3]).getTime();
        }

        m = s.match(/^(\d{4})[-\/\.](\d{1,2})[-\/\.](\d{1,2})/);
        if (m) {
            return new Date(+m[1], +m[2] - 1, +m[3]).getTime();
        }

        m = s.match(/^(\d{4})$/);
        if (m) {
            return new Date(+m[1], 0, 1).getTime();
        }

        return -Infinity;
    }

    function prepare(rawList) {
        items = rawList.map(function (raw) {
            var groups = {};

            CONFIG.fields.forEach(function (key, i) {
                var g   = String(i + 1);
                var val = trim(raw[key]);
                var arr = [];

                if (val !== '') {
                    if (key === '实装时间') {
                        var m = val.match(/^(\d{4})/);
                        if (m) arr.push(m[1]);
                    } else {
                        val.split(/[,，]/).forEach(function (s) {
                            s = trim(s);
                            if (s !== '' && arr.indexOf(s) < 0) arr.push(s);
                        });
                    }
                }
                groups[g] = arr;
            });

            var lname   = trim(raw['船名']).toLowerCase();
            var dateNum = parseClothDate(raw['实装时间']);

            return {
                raw     : raw,
                groups  : groups,
                lname   : lname,
                dateNum : dateNum
            };
        });

        // 按实装时间倒序排序（新 → 旧）

        items.sort(function (a, b) {
            return b.dateNum - a.dateNum;
        });
    }

    /* ======================= 筛选 + 搜索逻辑 ======================= */
    function hasValue(vals, v) {
        if (v === '') return vals.length === 0;
        return vals.indexOf(v) >= 0;
    }

    function matchItem(item) {
        for (var g in filters) {
            if (!Object.prototype.hasOwnProperty.call(filters, g)) continue;

            var f    = filters[g];
            var vals = item.groups[g] || [];

            if (f.AND && f.AND.length) {
                for (var i = 0; i < f.AND.length; i++) {
                    if (!hasValue(vals, f.AND[i])) return false;
                }
            }

            if (f.OR && f.OR.length) {
                var hit = false;
                for (var j = 0; j < f.OR.length; j++) {
                    if (hasValue(vals, f.OR[j])) { hit = true; break; }
                }
                if (!hit) return false;
            }
        }
        return true;
    }

    function applyFilter() {
        var base = $.isEmptyObject(filters)
            ? items.slice()
            : items.filter(matchItem);

        // 叠加船名搜索
        if (searchKeyword !== '') {
            var kw = searchKeyword.toLowerCase();
            base = base.filter(function (item) {
                return item.lname.indexOf(kw) >= 0;
            });
        }

        filtered = base;
    }

    /* ======================= 搜索框 ======================= */
    function buildSearchBar() {
        $searchBar = $(
            '<div class="cloth-search-bar">' +
              '<span class="cloth-search-hint"></span>' +
              '<span class="cloth-search-wrap">' +
                '<input type="text" class="cloth-search-input" ' +
                       'placeholder="请输入船名搜索…" aria-label="按船名搜索">' +
                '<button type="button" class="cloth-search-clear" ' +
                        'title="清除" aria-label="清除">×</button>' +
              '</span>' +
            '</div>'
        );

        $searchInput = $searchBar.find('.cloth-search-input');
        $searchClear = $searchBar.find('.cloth-search-clear');

        $searchInput.on('input', onSearchInput);
        $searchInput.on('keydown', function (e) {
            if (e.key === 'Escape' && $searchInput.val() !== '') {
                e.preventDefault();
                clearSearch();
            }
        });

        $searchClear.on('click', function () {
            clearSearch();
            $searchInput.focus();
        });

        $root.before($searchBar);
    }

    function onSearchInput() {
        if (searchTimer) clearTimeout(searchTimer);
        searchTimer = setTimeout(function () {
            searchTimer = null;

            var kw = trim($searchInput.val());
            if (kw === searchKeyword) return;

            searchKeyword = kw;
            $searchClear.toggle(kw !== '');
            $searchBar.find('.cloth-search-hint').text(kw ? '搜索：' : '');

            currentPage = 1;
            render();
        }, CONFIG.searchDebounce);
    }

    function clearSearch() {
        if (searchTimer) { clearTimeout(searchTimer); searchTimer = null; }
        $searchInput.val('');
        $searchClear.hide();
        $searchBar.find('.cloth-search-hint').text('');
        if (searchKeyword === '') return;
        searchKeyword = '';
        currentPage = 1;
        render();
    }

    /* ======================= 卡片渲染 ======================= */
    function buildCard(item) {
        var raw      = item.raw;
        var shipName = trim(raw['船名']);
        var shipType = trim(raw['舰种']);
        var clothTag = trim(raw['换装']);
        var clothNm  = trim(raw['换装名称']);
        var clothTime  = trim(raw['实装时间']);
        var imgFile  = shipName + clothTag + '.jpg';

        var el = document.createElement('div');
        el.className = 'ship_cloth_icon divsort';

        CONFIG.fields.forEach(function (key, i) {
            var g  = String(i + 1);
            var gv = item.groups[g] || [];

            el.setAttribute('data-param' + (i + 1), gv.join(','));
        });
        el.setAttribute('data-img', imgFile);

        if (!shipName) return el;

        var url = mw.util.getUrl(shipName);
        el.setAttribute('data-link', url);

        // ---- 信息区 ----
        var infoEl = document.createElement('div');
        infoEl.className = 'ship_cloth_icon_info';

        var clothNameEl = document.createElement('div');
        clothNameEl.className = 'ship_cloth_icon_clothName';
        clothNameEl.textContent = clothNm;
        infoEl.appendChild(clothNameEl);

        var textEl = document.createElement('div');
        textEl.className = 'ship_cloth_icon_text';

        var nameEl = document.createElement('div');
        nameEl.className = 'ship_cloth_icon_Name';
        nameEl.textContent = shipName;
        textEl.appendChild(nameEl);

        if (shipType) {
            var typeFile = 'ShipType-' + shipType + '.png';
            var typeUrl  = resolvedUrlCache[typeFile] || filePathUrl(typeFile);

            var typeEl = document.createElement('div');
            typeEl.className = 'ship_cloth_icon_type';

            var typeImg = document.createElement('img');
            typeImg.src     = typeUrl;
            typeImg.width   = CONFIG.typeIconWidth;
            typeImg.alt     = shipType;
            typeImg.loading = 'lazy';

            typeEl.appendChild(typeImg);
            textEl.appendChild(typeEl);
        }

        infoEl.appendChild(textEl);

        var clothTimeEl = document.createElement('div');
        clothTimeEl.className = 'ship_cloth_icon_clothTime';
        clothTimeEl.textContent = clothTime;
        infoEl.appendChild(clothTimeEl);

        el.appendChild(infoEl);

        // ---- 换装图片 ----
        var imgUrl = resolvedUrlCache[imgFile] || filePathUrl(imgFile);

        var a = document.createElement('a');
        a.href   = url;
        a.target = '_blank';
        a.title  = shipName + (clothNm ? ' · ' + clothNm : '');

        var img = document.createElement('img');
        img.width     = CONFIG.imgWidth;
        img.alt       = shipName + clothTag;
        img.className = 'cloth-img-pending';
        img.setAttribute('data-src', imgUrl);

        a.appendChild(img);
        el.appendChild(a);

        lazyImg(img);

        return el;
    }

    function lazyImg(img) {
        if (!imgObserver) { enqueueImg(img, 0); return; }
        imgObserver.observe(img);
    }

    /* ======================= 分页 ======================= */
    function pageList(cur, total) {
        var out  = [];
        var win  = 2;
        var last = 0;

        for (var i = 1; i <= total; i++) {
            if (i === 1 || i === total || Math.abs(i - cur) <= win) {
                if (last && i - last > 1) out.push('...');
                out.push(i);
                last = i;
            }
        }
        return out;
    }

    function makeBtn(text, target, disabled, isCurrent) {
        var $b = $('<a href="#" class="cloth-pager-btn"></a>').text(text);

        if (isCurrent) $b.addClass('current');

        if (disabled) {
            $b.addClass('disabled').on('click', function (e) { e.preventDefault(); });
            return $b;
        }

        $b.on('click', function (e) {
            e.preventDefault();
            if (currentPage === target) return;
            currentPage = target;
            render();
            scrollToTop();
        });
        return $b;
    }

    function renderPager(totalPages, totalItems) {
        if (!$pager) {
            $pager = $('<div class="cloth-pager" id="cloth-pager"></div>');
            $root.after($pager);
        }
        $pager.empty();

        if (totalItems === 0) return;

        $pager.append(
            $('<span class="cloth-pager-info"></span>').text(
                '共 ' + totalItems + ' 项，第 ' + currentPage + ' / ' + totalPages + ' 页'
            )
        );

        if (totalPages <= 1) return;

        var $nav = $('<span class="cloth-pager-nav"></span>');

        $nav.append(makeBtn('上一页', currentPage - 1, currentPage <= 1));

        pageList(currentPage, totalPages).forEach(function (p) {
            if (p === '...') {
                $nav.append('<span class="cloth-pager-ellipsis">…</span>');
            } else {
                $nav.append(makeBtn(String(p), p, false, p === currentPage));
            }
        });

        $nav.append(makeBtn('下一页', currentPage + 1, currentPage >= totalPages));

        $pager.append($nav);
    }

    function scrollToTop() {
        var top = $root.offset().top - 60;
        if ($(window).scrollTop() > top) {
            $('html, body').animate({ scrollTop: top }, 200);
        }
    }

    /* ======================= 主渲染 ======================= */
    function render() {
        applyFilter();

        var total = filtered.length;
        var pages = Math.max(1, Math.ceil(total / CONFIG.pageSize));

        if (currentPage > pages) currentPage = pages;
        if (currentPage < 1)     currentPage = 1;

        var start = (currentPage - 1) * CONFIG.pageSize;
        var slice = filtered.slice(start, start + CONFIG.pageSize);

        resetImgQueue();

        // 空结果
        if (total === 0) {
            var emptyText = searchKeyword
                ? '没有找到船名包含「' + searchKeyword + '」的换装'
                : '没有符合条件的换装';
            $root.empty().append(
                $('<div class="cloth-empty"></div>').text(emptyText)
            );
            renderPager(pages, total);
            return;
        }

        $root.empty().append('<div class="cloth-loading">图片地址解析中…</div>');

        var fileNames = collectFileNames(slice);

        batchResolveUrls(fileNames).done(function () {
            var frag = document.createDocumentFragment();
            slice.forEach(function (item) {
                frag.appendChild(buildCard(item));
            });

            $root.empty().append(frag);
            renderPager(pages, total);
        });
    }

    /* ======================= 筛选按钮 ======================= */
    function initOptions() {
        $('.cardSelectOption').each(function () {
            var $x     = $(this);
            var group  = trim($x.attr('data-group'));
            var option = trim($x.attr('data-option'));

            if (group === '' || option === undefined || option === null) return;

            var parts = String(option).split('|');

            $x.data('ckey', group);
            $x.data('cval', parts.length > 1 ? trim(parts[1]) : '');
            $x.data('copt', (trim($x.attr('data-opt')) || 'OR').toUpperCase());

            $x.off('click.clothpage').on('click.clothpage', onOptionClick);
        });
    }

    function onOptionClick(e) {
        e.preventDefault();

        var $x    = $(this);
        var group = $x.data('ckey');

        if (group === '0') {
            $('.cardSelectOption').removeClass('selected');
            filters     = {};
            currentPage = 1;
            render();
            return;
        }

        var val    = $x.data('cval');
        var opt    = $x.data('copt') === 'AND' ? 'AND' : 'OR';
        var turnOn = !$x.hasClass('selected');

        $x.toggleClass('selected', turnOn);

        if (!filters[group])      filters[group] = {};
        if (!filters[group][opt]) filters[group][opt] = [];

        var bucket = filters[group][opt];
        var idx    = bucket.indexOf(val);

        if (turnOn) {
            if (idx < 0) bucket.push(val);
        } else {
            if (idx >= 0) bucket.splice(idx, 1);
            if (bucket.length === 0) delete filters[group][opt];
            if ($.isEmptyObject(filters[group])) delete filters[group];
        }

        currentPage = 1;
        render();
    }

    /* ======================= 初始化 ======================= */
    function init() {
        $root = $(CONFIG.cardRoot);
        if (!$root.length) $root = $('#clothlist-container');
        if (!$root.length) return;

        if (started) return;
        started = true;

        addStyle();

        $('<link rel="preconnect" href="' + location.origin + '">').appendTo(document.head);

        buildSearchBar();

        $root.empty().append('<div class="cloth-loading">换装数据加载中…</div>');

        initImgObserver();
        initOptions();

        fetchJson().done(function (data) {
            prepare(data);
            currentPage = 1;
            render();
        }).fail(function (msg) {
            $root.empty().append(
                $('<div class="cloth-error"></div>').text('加载失败：' + msg)
            );
        });
    }

    $(function () {
        if (window.mw && mw.loader && mw.util) {
            mw.loader.using(['mediawiki.api', 'mediawiki.util'], function () {
                init();
            });
        } else {
            init();
        }
    });

})();
